class.description:
The WebRTC transport sends every offer, answer and ICE candidate through a signaler, and receives the other peer's through it. Pass a subclass as the [code]signaler[/code] setting of the WebRTC transport. The default uses public WebTorrent trackers and needs no server.
[codeblock]
class_name RelaySignaler
extends NetwWebRTCSignaler

var _socket := WebSocketPeer.new()
var _room := ""

func _open(room_id: String, local_peer_id: int) -> Error:
    _room = room_id if not room_id.is_empty() else _new_room()
    return _socket.connect_to_url("wss://rooms.example/%s" % _room)

func _room_id() -> String:
    return _room

func _send(
        to_peer_id: int, to_address: String,
        kind: String, payload: Dictionary,
) -> void:
    _socket.send_text(JSON.stringify({to = to_address, kind = kind,
            body = payload}))

func _poll(_delta: float) -> void:
    _socket.poll()
    if _socket.get_ready_state() == WebSocketPeer.STATE_OPEN:
        report_ready()
    while _socket.get_available_packet_count() > 0:
        var m: Dictionary = JSON.parse_string(
                _socket.get_packet().get_string_from_utf8())
        receive(m.from_peer, m.from, m.kind, m.body)

func _close() -> void:
    _socket.close()
[/codeblock]
Report back by calling [method receive], [method report_ready], [method report_lost] and [method report_unreachable].
[code]kind[/code] in [method receive] and [method _send] is [code]"offer"[/code], [code]"answer"[/code] or [code]"candidate"[/code]. Offers and answers already include the gathered candidates, so one message per peer is enough.
The default signaler warns once when every tracker fails. Enable [code]networked/webrtc/warn_on_tracker_failure[/code] to also warn for each tracker that fails.
